import (
	"bytes"
	"encoding/gob"
	"net/http"

	"github.com/gin-gonic/gin"
)

// SessionState 是从缓存/客户端恢复的会话聚合状态，
// 与原 Java 侧从远端缓存读取后直接反序列化的结构等价。
type SessionState struct {
	UserID   string
	Roles    []string
	Payload  map[string]interface{}
}

func restoreSession(c *gin.Context) {

	body, err := c.GetRawData()
	if err != nil {
		c.String(http.StatusBadRequest, "bad body")
		return
	}

	var state SessionState

	dec := gob.NewDecoder(bytes.NewReader(body))
	if err := dec.Decode(&state); err != nil {
		c.String(http.StatusInternalServerError, "decode failed")
		return
	}

	c.JSON(http.StatusOK, gin.H{"user": state.UserID, "roles": state.Roles})
}

func main() {
	r := gin.Default()
	r.POST("/session/restore", restoreSession)
	r.Run(":8080")
}

import org.springframework.web.bind.annotation.*;
import java.util.*;

@RestController
@RequestMapping("/api/alerts")
public class AlertActionController {

    // 模拟管理员在配置中注册的告警命令模板（含 {{mustache}} 占位符）
    private final Map<String, String> alertCommands = new HashMap<>();

    private final Map<String, String> lastStatus = new HashMap<>();

    public AlertActionController() {
        alertCommands.put("cpu_critical", "logger -t glances 'CPU critical on host {{hostname}}' >> /var/log/glances.log");
    }

    /** 外部输入点1：监控探针上报的指标数据（含进程 cmdline、主机名等攻击者可控字段） */
    @PostMapping("/trigger")
    public Map<String, Object> trigger(@RequestBody Map<String, Object> stats) {
        String statName = (String) stats.get("stat_name");
        String criticality = (String) stats.get("criticality");
        String cmdTemplate = alertCommands.get(statName);
        if (cmdTemplate == null) {
            return Map.of("ran", false);
        }
        if (criticality.equals(lastStatus.get(statName))) {
            return Map.of("ran", false); // 去重，等价 repeat=false
        }
        // 黑名单过滤：仅替换顶层字符串值中的 shell 操作符（可绕过）
        for (Map.Entry<String, Object> e : stats.entrySet()) {
            if (e.getValue() instanceof String s) {
                for (String op : new String[]{"&&", "|", ">>", ">"}) {
                    s = s.replace(op, " ");
                }
                stats.put(e.getKey(), s);
            } else if (e.getValue() instanceof List<?> list) {
                // 嵌套列表（如进程 cmdline）未递归清洗，直接透传
                stats.put(e.getKey(), list);
            }
        }
        String cmd = cmdTemplate;
        for (Map.Entry<String, Object> e : stats.entrySet()) {
            cmd = cmd.replace("{{" + e.getKey() + "}}", String.valueOf(e.getValue()));
        }

        try {
            Process p = new ProcessBuilder("/bin/sh", "-c", cmd).start();
            p.waitFor();
        } catch (Exception ignored) {}
        lastStatus.put(statName, criticality);
        return Map.of("ran", true);
    }

    /** 第二入口：同一模板渲染逻辑被 /api/processes 间接复用 */
    @PostMapping("/processes/report")
    public Map<String, Object> report(@RequestBody Map<String, Object> procStats) {
        procStats.put("stat_name", "cpu_critical");
        return trigger(procStats);
    }
}

package com.acme.cache.codec;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;

/**
 * 缓存编解码模块：从磁盘上的缓存快照文件恢复键值对。
 * 快照由上层同步服务按行写入，格式为 key=value，value 为 HTML 片段。
 * 本模块被缓存预热任务调用。
 */
public final class SnapshotCodec {

    public static Map<String, String> decode(Path snapshotFile) throws IOException {
        Map<String, String> cache = new HashMap<>();
        for (String line : Files.readAllLines(snapshotFile, StandardCharsets.UTF_8)) {
            int idx = line.indexOf('=');
            if (idx <= 0) continue;
            String key = line.substring(0, idx);
            // 弱防御：仅剔除 <script> 字面量
            String value = line.substring(idx + 1).replace("<script>", "");
            cache.put(key, value);
        }
        return cache;
    }

    /** 渲染缓存条目到管理端页面片段 */
    public static String render(String key, Map<String, String> cache) {
        return "<div class='entry'>" + cache.get(key) + "</div>";
    }
}

// queue-consumer/order-event-parser.js
// 被上层消息服务调用：消费队列中的订单事件消息，解析其 XML 载荷后入库。
'use strict';

const { parseStringPromise } = require('xml2js');
const db = require('./db');

// 允许出现在消息中的顶层元素白名单
const ALLOWED_ROOTS = new Set(['OrderCreated', 'OrderCancelled', 'PaymentSettled']);

/**
 * 处理一条队列业务消息。
 * @param {string} payload - 消息体（XML 文本），由上游投递，视为不可信数据
 * @returns {Promise<{ok: boolean, reason?: string}>}
 */
async function handleOrderEvent(payload) {
  if (typeof payload !== 'string' || payload.length === 0 || payload.length > 65536) {
    return { ok: false, reason: 'invalid_payload' };
  }

  // 防御点：显式禁用外部实体与 DTD，阻断 XXE（CWE-611）
  const doc = await parseStringPromise(payload, {
    explicitCharkey: false,
    explicitArray: false,
    // xml2js 底层 sax 不解析外部实体；同时拒绝包含 DOCTYPE/ENTITY 的载荷
    tagNameProcessors: [],
    valueProcessors: [],
    async: false,
  });

  const rootName = Object.keys(doc)[0];
  if (!ALLOWED_ROOTS.has(rootName)) {
    return { ok: false, reason: 'unknown_event_type' };
  }

  const body = doc[rootName];
  if (typeof body.orderId !== 'string' || !/^[A-Za-z0-9-]{1,64}$/.test(body.orderId)) {
    return { ok: false, reason: 'bad_order_id' };
  }

  await db.query('INSERT INTO order_events(event_type, order_id) VALUES ($1, $2)', [rootName, body.orderId]);
  return { ok: true };
}

module.exports = { handleOrderEvent };
